const configuredClientOrigins=()=>[...(process.env.CLIENT_URLS??'').split(','),process.env.CLIENT_URL??'',...(process.env.NODE_ENV==='production'?[productionClientUrl]:[])].map(value=>value.trim().replace(/\/$/,'')).filter(Boolean);
const defaultClientUrl=()=>{const origins=configuredClientOrigins();if(process.env.NODE_ENV==='production')return origins.find(origin=>{try{return !['localhost','127.0.0.1'].includes(new URL(origin).hostname)}catch{return false}})??productionClientUrl;return origins[0]??'http://localhost:5173'};
const safeClientOrigin=(value:string|undefined)=>{if(!value)return defaultClientUrl();try{const origin=new URL(value).origin,local=['localhost','127.0.0.1'].includes(new URL(origin).hostname);if(process.env.NODE_ENV!=='production'&&local)return origin;if(configuredClientOrigins().includes(origin)&&!local)return origin}catch{}return defaultClientUrl()};
const createOAuthState=(returnOrigin:string)=>{const payload=Buffer.from(JSON.stringify({returnOrigin,expiresAt:Date.now()+10*60*1000,nonce:randomBytes(16).toString('hex')})).toString('base64url'),signature=createHmac('sha256',adminSecret()).update(payload).digest('base64url');return `${payload}.${signature}`};
const readOAuthState=(state:string)=>{const [payload,signature]=state.split('.');if(!payload||!signature)return null;const expected=Buffer.from(createHmac('sha256',adminSecret()).update(payload).digest('base64url')),received=Buffer.from(signature);if(expected.length!==received.length||!timingSafeEqual(expected,received))return null;try{const value=JSON.parse(Buffer.from(payload,'base64url').toString()) as {returnOrigin?:string;expiresAt?:number};return Number(value.expiresAt)>Date.now()?safeClientOrigin(value.returnOrigin):null}catch{return null}};
const authCookieOptions=()=>({httpOnly:true,sameSite:(process.env.NODE_ENV==='production'?'none':'lax') as 'none'|'lax',secure:process.env.NODE_ENV==='production',path:'/'});
const cookieValue=(req:Request,name:string)=>{const value=(req.headers.cookie??'').split(';').map(item=>item.trim()).find(item=>item.startsWith(`${name}=`))?.slice(name.length+1);if(value===undefined)return undefined;try{return decodeURIComponent(value)}catch{return value}};
const tokenHash=(token:string)=>createHash('sha256').update(token).digest('hex');
const publicCustomer=(customer:any)=>({id:String(customer._id),fullName:customer.fullName,phone:customer.phone??'',email:customer.email,address:customer.address??'',avatarUrl:customer.avatarUrl??'',authProviders:customer.authProviders??[],createdAt:customer.createdAt});
async function passwordHash(password:string,salt:string){return (await scrypt(password,salt,64) as Buffer).toString('hex')}
async function issueSession(res:Response,customerId:mongoose.Types.ObjectId){await ensureDatabase();const expiresAt=new Date(Date.now()+30*24*60*60*1000);for(let attempt=0;attempt<3;attempt++){const token=randomBytes(32).toString('hex');try{await CustomerSession.create({customerId,tokenHash:tokenHash(token),expiresAt});res.cookie(sessionCookie,token,{...authCookieOptions(),maxAge:30*24*60*60*1000});return}catch(error:any){if(error?.code!==11000||attempt===2)throw error}}throw new Error('CUSTOMER_SESSION_CREATE_FAILED')}
async function issueOAuthHandoff(customerId:mongoose.Types.ObjectId){await ensureDatabase();const code=randomBytes(32).toString('base64url');await OAuthHandoff.create({customerId,codeHash:tokenHash(code),expiresAt:new Date(Date.now()+5*60*1000)});return code}
async function currentCustomer(req:Request){const token=cookieValue(req,sessionCookie);if(!token)return null;const session=await CustomerSession.findOne({tokenHash:tokenHash(token),expiresAt:{$gt:new Date()}}).lean();if(!session)return null;return Customer.findOne({_id:session.customerId,active:true}).lean()}
async function requireCustomer(req:Request,res:Response,next:NextFunction){try{const customer=await currentCustomer(req);if(!customer)return res.status(401).json({error:{code:'AUTH_REQUIRED',message:'Please sign in before booking.'}});res.locals.customer=customer;next()}catch(error){next(error)}}
const adminSecret=()=>process.env.SESSION_SECRET||process.env.ADMIN_PASSWORD||'';
const signAdminPayload=(payload:string)=>createHmac('sha256',adminSecret()).update(payload).digest('base64url');
const createAdminToken=()=>{const payload=Buffer.from(JSON.stringify({expiresAt:Date.now()+12*60*60*1000,nonce:randomBytes(12).toString('hex')})).toString('base64url');return `${payload}.${signAdminPayload(payload)}`};
const createRealtimeToken=()=>{const payload=Buffer.from(JSON.stringify({expiresAt:Date.now()+60*1000,purpose:'realtime',nonce:randomBytes(8).toString('hex')})).toString('base64url');return `${payload}.${signAdminPayload(payload)}`};
const validAdminToken=(token:string|undefined)=>{if(!token)return false;const [payload,signature]=token.split('.');if(!payload||!signature)return false;const expected=Buffer.from(signAdminPayload(payload)),received=Buffer.from(signature);if(expected.length!==received.length||!timingSafeEqual(expected,received))return false;try{return Number(JSON.parse(Buffer.from(payload,'base64url').toString()).expiresAt)>Date.now()}catch{return false}};
function requireAdmin(req:Request,res:Response,next:NextFunction){if(!validAdminToken(cookieValue(req,adminCookie)))return res.status(401).json({error:{code:'ADMIN_AUTH_REQUIRED',message:'Administrator sign-in required.'}});next()}
export const isAdminHeaders=(request:{url?:string;cookie?:string})=>{const queryToken=request.url?new URL(request.url,'http://localhost').searchParams.get('token')??undefined:undefined,cookieToken=(request.cookie??'').split(';').map(value=>value.trim()).find(value=>value.startsWith(`${adminCookie}=`))?.slice(adminCookie.length+1);return validAdminToken(queryToken)||validAdminToken(cookieToken)};
const title=(value:string)=>value.replace(/(^|_)(\w)/g,(_match,prefix:string,char:string)=>`${prefix?' ':''}${char.toUpperCase()}`);
const appointmentDto=(item:any)=>{
 const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Colombo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(item.startAt)).map(part=>[part.type,part.value]));
 return {id:String(item._id),bookingReference:item.bookingReference,serviceId:item.serviceSnapshot?.serviceId?String(item.serviceSnapshot.serviceId):'',date:`${parts.year}-${parts.month}-${parts.day}`,time:`${parts.hour}:${parts.minute}`,customer:item.guest?.name??'',phone:item.guest?.phone??'',email:item.guest?.email??'',service:item.serviceSnapshot?.name??'',stylist:item.staffName??'Any available stylist',status:title(String(item.status)),source:title(String(item.bookingSource??'web')),amount:item.serviceSnapshot?.price??0,startAt:item.startAt,notes:item.notes??''};
};
