const localDateTime=(date:string,time:string)=>new Date(`${date}T${time}:00+05:30`);
const minutes=(time:string)=>{const [hour=0,minute=0]=time.split(':').map(Number);return hour*60+minute};
const timeLabel=(value:number)=>`${String(Math.floor(value/60)).padStart(2,'0')}:${String(value%60).padStart(2,'0')}`;
async function staffWindow(staff:any,date:string){const dayStart=localDateTime(date,'00:00'),dayEnd=new Date(dayStart.getTime()+24*60*60*1000);if((staff.leavePeriods??[]).some((leave:any)=>new Date(leave.startAt)<dayEnd&&new Date(leave.endAt)>dayStart))return null;const override=(staff.availability as any)?.[date];if(override)return override.available?override:null;const day=dayStart.getDay(),names=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'],recurring=(staff.workingSchedule as any)?.[day]??(staff.workingSchedule as any)?.[names[day]!];if(recurring)return recurring.available===false?null:{available:true,start:recurring.start??'09:00',end:recurring.end??'18:00'};if(day===0)return null;const settings=await BusinessSettings.findOne().lean(),hours=(settings?.openingHours as any)??{};return {available:true,start:hours.open??'09:00',end:hours.close??'19:00'}}
async function ensureDatabase(){if(mongoose.connection.readyState===1)return;if(mongoose.connection.readyState===2){await mongoose.connection.asPromise();return}const uri=process.env.MONGODB_URI;if(!uri)throw new Error('DATABASE_NOT_CONFIGURED');await mongoose.connect(uri,{dbName:'salon_tiran',serverSelectionTimeoutMS:8_000})}
async function sendEmail(recipient:string,subject:string,html:string,template:string,context:{customerId?:any;appointmentId?:any}={}){const provider=(process.env.EMAIL_PROVIDER??'').toLowerCase(),apiKey=process.env.EMAIL_API_KEY,from=process.env.EMAIL_FROM;if(provider!=='resend'||!apiKey||!from){await NotificationLog.create({...context,recipient,template,status:'skipped',error:'Email provider is not configured'});return false}try{const response=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:`Bearer ${apiKey}`,'Content-Type':'application/json'},body:JSON.stringify({from,to:[recipient],subject,html})});if(!response.ok)throw new Error(`EMAIL_PROVIDER_${response.status}`);await NotificationLog.create({...context,recipient,template,status:'sent',sentAt:new Date()});return true}catch(error){await NotificationLog.create({...context,recipient,template,status:'failed',error:error instanceof Error?error.message:'Email delivery failed'});console.error('Email notification failed:',error);return false}}
async function sendAppointmentEmail(item:any,template:'created'|'cancelled'|'status'){const email=item.guest?.email;if(!email)return;const data=appointmentDto(item),subject=template==='created'?`Appointment request ${data.bookingReference}`:template==='cancelled'?`Appointment cancelled ${data.bookingReference}`:`Appointment updated ${data.bookingReference}`,message=template==='created'?'We received your appointment request.':template==='cancelled'?'Your appointment has been cancelled.':`Your appointment is now ${data.status}.`;await sendEmail(email,subject,`<h2>${message}</h2><p><strong>${data.service}</strong></p><p>${data.date} at ${data.time} with ${data.stylist}</p><p>Reference: ${data.bookingReference}</p>`,template,{customerId:item.customerId,appointmentId:item._id})}
