const slugify=(value:string)=>value.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
async function uniqueServiceSlug(name:string,excludeId?:string){const base=slugify(name)||'service';let slug=base,index=2;while(await Service.exists({slug,...(excludeId?{_id:{$ne:excludeId}}:{})}))slug=`${base}-${index++}`;return slug}
async function migrateLegacyServices(){const legacy=await AdminState.findOne({key:'services'}).lean();if(!Array.isArray(legacy?.data)||!legacy.data.length)return;for(const item of legacy.data){const input=serviceInput.parse(item),existing=await Service.findOne({name:input.name}).lean();if(existing)continue;await Service.create({name:input.name,slug:await uniqueServiceSlug(input.name),category:input.category,description:input.description,price:input.price,durationMinutes:input.duration,active:input.active})}}
const starterCatalog=[
 {audience:'Ladies',description:'Beauty and grooming services designed for women.',categories:[{name:'Hair',services:[['Ladies Signature Cut','Consultation-led wash, cut and finish.',4500,60],['Hair Colour Refresh','Root colour or tonal refresh with professional finish.',8500,120],['Keratin Smoothing','Long-lasting smoothing and frizz control ritual.',18000,180],['Bridal Hair Styling','Trial-ready bridal styling tailored to your look.',15000,150]]},{name:'Face',services:[['Radiance Facial','Deep cleanse, exfoliation and hydration for renewed skin.',6500,75],['Eyebrow Shaping','Precise shaping for a balanced natural finish.',1800,25]]},{name:'Nails',services:[['Classic Manicure','Nail shaping, cuticle care and classic polish.',3500,50],['Gel Manicure','Long-wear gel colour with complete nail preparation.',5500,70]]}]},
 {audience:'Gents',description:'Modern grooming and care services designed for men.',categories:[{name:'Hair',services:[['Gents Precision Cut','Consultation, precision cut, wash and finish.',3000,45],['Fade & Beard Detail','Clean fade paired with beard shaping and detailing.',4200,60],['Grey Blending','Natural-looking grey camouflage and finish.',6000,75]]},{name:'Face',services:[['Gents Deep Clean Facial','Purifying facial focused on congestion and hydration.',5500,60],['Beard Sculpt','Hot towel preparation, beard design and finish.',2200,30]]},{name:'Nails',services:[['Gents Hand Grooming','Nail and cuticle care with a clean natural finish.',3000,40],['Foot Grooming','Complete foot and nail care treatment.',4500,55]]}]}];
