async function ensureStarterCatalog(){await ensureDatabase();const staff=await Staff.find({active:true}).select('_id').lean(),staffIds=staff.map(item=>item._id),categoryMap=new Map<string,any>();for(const [ai,group] of starterCatalog.entries()){const audience=await ServiceAudience.findOneAndUpdate({slug:slugify(group.audience)},{$set:{imageUrl:catalogImages[group.audience]},$setOnInsert:{name:group.audience,slug:slugify(group.audience),description:group.description,displayOrder:ai,active:true}},{upsert:true,new:true});for(const [ci,groupCategory] of group.categories.entries()){const imageUrl=catalogImages[`${group.audience}:${groupCategory.name}`],category=await ServiceCategory.findOneAndUpdate({audienceId:audience._id,slug:slugify(groupCategory.name)},{$set:{imageUrl},$setOnInsert:{audienceId:audience._id,name:groupCategory.name,slug:slugify(groupCategory.name),description:`${groupCategory.name} services for ${group.audience.toLowerCase()}.`,displayOrder:ci,active:true}},{upsert:true,new:true});categoryMap.set(`${group.audience}:${groupCategory.name}`,category);for(const [si,serviceData] of groupCategory.services.entries()){const [name,description,price,duration]=serviceData as [string,string,number,number],service=await Service.findOneAndUpdate({slug:slugify(name)},{$set:{imageUrl},$setOnInsert:{name,slug:slugify(name),category:groupCategory.name,categoryId:category._id,description,price,durationMinutes:duration,staffIds,active:true,displayOrder:si}},{upsert:true,new:true});if(staffIds.length)await Staff.updateMany({_id:{$in:staffIds}},{$addToSet:{offeredServices:service._id}})}}}const legacy=await Service.find({$or:[{categoryId:{$exists:false}},{categoryId:null},{imageUrl:''},{imageUrl:{$exists:false}}]}).lean();for(const service of legacy){const text=`${service.name} ${service.category}`.toLowerCase(),audience=text.includes('gent')||text.includes('beard')||text.includes('fade')?'Gents':'Ladies',category=text.includes('nail')||text.includes('manicure')||text.includes('pedicure')?'Nails':text.includes('face')||text.includes('facial')||text.includes('brow')||text.includes('beard')?'Face':'Hair',target=categoryMap.get(`${audience}:${category}`);if(target)await Service.updateOne({_id:service._id},{$set:{categoryId:target._id,category:target.name,imageUrl:catalogImages[`${audience}:${category}`]}})}}
async function catalogData(activeOnly=false){await ensureStarterCatalog();const filter=activeOnly?{active:true}:{},[audiences,categories,services]=await Promise.all([ServiceAudience.find(filter).sort({displayOrder:1,name:1}).lean(),ServiceCategory.find(filter).sort({displayOrder:1,name:1}).lean(),Service.find(filter).sort({displayOrder:1,name:1}).lean()]);return {audiences:audiences.map(audienceDto),categories:categories.map(categoryDto),services:services.map(serviceDto)}}
async function syncServiceStaff(serviceId:string,staffIds:string[]){const id=new mongoose.Types.ObjectId(serviceId),members=staffIds.map(value=>new mongoose.Types.ObjectId(value));await Promise.all([Staff.updateMany({_id:{$in:members}},{$addToSet:{offeredServices:id}}),Staff.updateMany({_id:{$nin:members},offeredServices:id},{$pull:{offeredServices:id}})])}
async function syncStaffServices(staffId:string,serviceIds:string[]){const id=new mongoose.Types.ObjectId(staffId),services=serviceIds.map(value=>new mongoose.Types.ObjectId(value));await Promise.all([Service.updateMany({_id:{$in:services}},{$addToSet:{staffIds:id}}),Service.updateMany({_id:{$nin:services},staffIds:id},{$pull:{staffIds:id}})])}
async function googleCustomer(profile:{sub:string;email:string;name?:string;picture?:string}){await ensureDatabase();const googleId=profile.sub,email=profile.email.toLowerCase(),displayName=profile.name||email.split('@')[0]||'Google Customer';let customer=await Customer.findOne({$or:[{googleId},{email}]});if(customer){if(customer.googleId&&customer.googleId!==googleId)throw new Error('GOOGLE_ACCOUNT_CONFLICT');customer.googleId=googleId;if(profile.picture)customer.avatarUrl=profile.picture;customer.fullName=customer.fullName||displayName;customer.authProviders=[...new Set([...(customer.authProviders??[]),'google'])];customer.lastLoginAt=new Date();await customer.save();return customer}try{return await Customer.create({fullName:displayName,email,googleId,...(profile.picture?{avatarUrl:profile.picture}:{}),authProviders:['google'],lastLoginAt:new Date()})}catch(error:any){if(error?.code!==11000)throw error;customer=await Customer.findOne({$or:[{googleId},{email}]});if(!customer||customer.googleId&&customer.googleId!==googleId)throw error;customer.googleId=googleId;customer.authProviders=[...new Set([...(customer.authProviders??[]),'google'])];customer.lastLoginAt=new Date();if(profile.picture)customer.avatarUrl=profile.picture;await customer.save();return customer}}
const googleRedirectUri=()=>process.env.NODE_ENV==='production'?`${productionApiUrl}/api/auth/google/callback`:process.env.GOOGLE_REDIRECT_URI;
const calendarRedirectUri=()=>process.env.NODE_ENV==='production'?`${productionApiUrl}/api/admin/google-calendar/callback`:process.env.GOOGLE_CALENDAR_REDIRECT_URI??process.env.GOOGLE_REDIRECT_URI?.replace('/auth/google/callback','/admin/google-calendar/callback');
const calendarTokenKey=()=>createHash('sha256').update(process.env.SESSION_SECRET||process.env.GOOGLE_CLIENT_SECRET||'').digest();
const encryptToken=(value:string)=>{const iv=randomBytes(12),cipher=createCipheriv('aes-256-gcm',calendarTokenKey(),iv),encrypted=Buffer.concat([cipher.update(value,'utf8'),cipher.final()]);return `${iv.toString('base64url')}.${cipher.getAuthTag().toString('base64url')}.${encrypted.toString('base64url')}`};
const decryptToken=(value:string)=>{const [iv,tag,encrypted]=value.split('.');if(!iv||!tag||!encrypted)throw new Error('INVALID_STORED_CALENDAR_TOKEN');const decipher=createDecipheriv('aes-256-gcm',calendarTokenKey(),Buffer.from(iv,'base64url'));decipher.setAuthTag(Buffer.from(tag,'base64url'));return Buffer.concat([decipher.update(Buffer.from(encrypted,'base64url')),decipher.final()]).toString('utf8')};
async function calendarAccessToken(){const connection=await GoogleCalendarConnection.findOne({key:'primary'}).lean(),clientId=process.env.GOOGLE_CLIENT_ID,clientSecret=process.env.GOOGLE_CLIENT_SECRET;if(!connection||!clientId||!clientSecret)return null;const response=await fetch('https://oauth2.googleapis.com/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({client_id:clientId,client_secret:clientSecret,refresh_token:decryptToken(connection.encryptedRefreshToken),grant_type:'refresh_token'})});if(!response.ok)throw new Error(`GOOGLE_CALENDAR_TOKEN_REFRESH_FAILED_${response.status}`);const body=await response.json() as {access_token?:string};if(!body.access_token)throw new Error('GOOGLE_CALENDAR_ACCESS_TOKEN_MISSING');return {accessToken:body.access_token,calendarId:connection.calendarId||'primary'}}
