router.post('/admin/service-categories',requireAdmin,async(req,res,next)=>{try{const input=categoryInput.parse(req.body);if(!await ServiceAudience.exists({_id:input.audienceId}))return res.status(404).json({error:{code:'AUDIENCE_NOT_FOUND',message:'Audience not found'}});const item=await ServiceCategory.create({...input,slug:slugify(input.name)});return res.status(201).json({data:categoryDto(item.toObject())})}catch(e){next(e)}});
router.patch('/admin/service-categories/:id',requireAdmin,async(req,res,next)=>{try{const input=categoryInput.partial().parse(req.body),item=await ServiceCategory.findByIdAndUpdate(req.params.id,{$set:{...input,...(input.name?{slug:slugify(input.name)}:{})}},{new:true,runValidators:true}).lean();if(!item)return res.status(404).json({error:{code:'NOT_FOUND',message:'Category not found'}});if(input.name)await Service.updateMany({categoryId:item._id},{$set:{category:input.name}});return res.json({data:categoryDto(item)})}catch(e){next(e)}});
router.delete('/admin/service-categories/:id',requireAdmin,async(req,res,next)=>{try{if(await Service.exists({categoryId:req.params.id}))return res.status(409).json({error:{code:'CATEGORY_IN_USE',message:'Delete or move its services first.'}});await ServiceCategory.findByIdAndDelete(req.params.id);return res.status(204).send()}catch(e){next(e)}});
router.post('/admin/services',requireAdmin,async(req,res,next)=>{try{await ensureDatabase();const input=serviceInput.parse(req.body),category=input.categoryId?await ServiceCategory.findById(input.categoryId).lean():null,item=await Service.create({name:input.name,slug:await uniqueServiceSlug(input.name),category:category?.name??input.category,categoryId:category?._id,description:input.description,imageUrl:input.imageUrl,price:input.price,durationMinutes:input.duration,staffIds:input.staffIds,active:input.active});await syncServiceStaff(String(item._id),input.staffIds);return res.status(201).json({data:serviceDto(item.toObject())})}catch(e){next(e)}});
router.patch('/admin/services/:id',requireAdmin,async(req,res,next)=>{try{if(!mongoose.isValidObjectId(req.params.id))return res.status(400).json({error:{code:'INVALID_ID',message:'Invalid service id'}});const input=serviceInput.partial().parse(req.body),values:any={...input};if(input.duration!==undefined){values.durationMinutes=input.duration;delete values.duration}if(input.categoryId){const category=await ServiceCategory.findById(input.categoryId).lean();if(!category)return res.status(404).json({error:{code:'CATEGORY_NOT_FOUND',message:'Category not found'}});values.category=category.name}if(input.name!==undefined)values.slug=await uniqueServiceSlug(input.name,String(req.params.id));if(input.staffIds!==undefined){values.staffIds=input.staffIds;await syncServiceStaff(String(req.params.id),input.staffIds)}const item=await Service.findByIdAndUpdate(req.params.id,{$set:values},{new:true,runValidators:true}).lean();if(!item)return res.status(404).json({error:{code:'NOT_FOUND',message:'Service not found'}});return res.json({data:serviceDto(item)})}catch(e){next(e)}});
router.delete('/admin/services/:id',requireAdmin,async(req,res,next)=>{try{if(!mongoose.isValidObjectId(req.params.id))return res.status(400).json({error:{code:'INVALID_ID',message:'Invalid service id'}});const item=await Service.findByIdAndDelete(req.params.id);if(!item)return res.status(404).json({error:{code:'NOT_FOUND',message:'Service not found'}});await Staff.updateMany({offeredServices:item._id},{$pull:{offeredServices:item._id}});return res.status(204).send()}catch(e){next(e)}});
router.get('/admin/staff',requireAdmin,async(_req,res)=>{try{await ensureDatabase();await migrateLegacyStaff();return res.json({data:(await Staff.find().sort({createdAt:1}).lean()).map(staffDto)})}catch(error){console.error('Staff collection load failed:',error);return res.status(500).json({error:{code:'STAFF_LOAD_FAILED',message:error instanceof Error?error.message:'Could not load staff'}})}});
router.put('/admin/staff',requireAdmin,async(req,res,next)=>{try{await ensureDatabase();const input=z.object({data:z.array(staffInput)}).parse(req.body),keptIds:string[]=[];for(const member of input.data){const values={displayName:member.name,role:member.role,services:member.services,offeredServices:member.offeredServiceIds,active:member.active,availability:member.availability??{}};if(member.id&&mongoose.isValidObjectId(String(member.id))){const updated=await Staff.findByIdAndUpdate(String(member.id),{$set:values},{new:true,runValidators:true});if(updated){keptIds.push(String(updated._id));await syncStaffServices(String(updated._id),member.offeredServiceIds);continue}}const created=await Staff.create(values);keptIds.push(String(created._id));await syncStaffServices(String(created._id),member.offeredServiceIds)}const removed=await Staff.find({_id:{$nin:keptIds.map(id=>new mongoose.Types.ObjectId(id))}}).select('_id').lean(),removedIds=removed.map(item=>item._id);await Promise.all([Staff.deleteMany({_id:{$in:removedIds}}),Service.updateMany({staffIds:{$in:removedIds}},{$pull:{staffIds:{$in:removedIds}}})]);const items=await Staff.find().sort({createdAt:1}).lean();return res.json({data:items.map(staffDto)})}catch(e){next(e)}});
router.get('/admin/bootstrap',requireAdmin,async(_req,res,next)=>{try{await Promise.all([migrateLegacyServices(),migrateLegacyStaff()]);const [states,appointments,customers,services,staff]=await Promise.all([AdminState.find({key:{$in:['portfolio','settings']}}).lean(),Appointment.find().sort({startAt:-1}).lean(),Customer.find().sort({createdAt:-1}).lean(),Service.find().sort({displayOrder:1,createdAt:1}).lean(),Staff.find().sort({createdAt:1}).lean()]),state={...Object.fromEntries(states.map(item=>[item.key,item.data])),services:services.map(serviceDto),staff:staff.map(staffDto)},byCustomer=new Map<string,any[]>();for(const appointment of appointments){if(!appointment.customerId)continue;const key=String(appointment.customerId),items=byCustomer.get(key)??[];items.push(appointment);byCustomer.set(key,items)}const customerData=customers.map(customer=>{const bookings=byCustomer.get(String(customer._id))??[],completed=bookings.filter(item=>item.status==='completed');return {...publicCustomer(customer),bookings:bookings.map(appointmentDto),totalBookings:bookings.length,totalSpend:completed.reduce((sum,item)=>sum+(item.serviceSnapshot?.price??0),0),lastBooking:bookings[0]?.startAt??null}});return res.json({data:{state,appointments:appointments.map(appointmentDto),customers:customerData}})}catch(e){next(e)}});
router.get('/appointments',requireAdmin,async(_req,res,next)=>{try{const items=await Appointment.find().sort({startAt:-1}).lean();return res.json({data:items.map(appointmentDto)})}catch(e){next(e)}});
router.post('/appointments',requireCustomer,async(req,res,next)=>{try{
 const input=booking.parse(req.body);
 const customer=res.locals.customer;
 const existing=await Appointment.findOne({idempotencyKey:input.idempotencyKey}).lean();
 if(existing)return res.status(200).json({data:appointmentDto(existing),idempotent:true});
 const service=mongoose.isValidObjectId(input.serviceId)?await Service.findOne({_id:input.serviceId,active:true}).lean():await Service.findOne({slug:input.serviceId,active:true}).lean(),serviceData=service;
 if(!serviceData)return res.status(404).json({error:{code:'SERVICE_NOT_FOUND',message:'Service not found'}});
 const endAt=appointmentEnd(input.startAt,serviceData.durationMinutes,serviceData.bufferMinutes??0);
 assertBookable(input.startAt,endAt);
 const staffId=input.staffId&&mongoose.isValidObjectId(input.staffId)?input.staffId:undefined,staff=staffId?await Staff.findOne({_id:staffId,active:true,offeredServices:service?._id}).lean():null,staffName=staff?.displayName;
 if(!staffName)return res.status(400).json({error:{code:'STAFF_REQUIRED',message:'Please select an available hairdresser.'}});
 const requestedDate=colomboDate(input.startAt),window=await staffWindow(staff,requestedDate);if(!window||input.startAt<localDateTime(requestedDate,window.start)||endAt>localDateTime(requestedDate,window.end))return res.status(409).json({error:{code:'OUTSIDE_AVAILABILITY',message:'That hairdresser is not available at this time.'}});
 const conflict=await Appointment.exists({staffName,status:{$in:reservingStatuses},startAt:{$lt:endAt},endAt:{$gt:input.startAt}});if(conflict)return res.status(409).json({error:{code:'SLOT_UNAVAILABLE',message:'That time has just become unavailable.'}});
 const settings=await BusinessSettings.findOne().lean(),status=settings?.bookingSettings?.approval==='automatic'?'confirmed':'pending';
 const item=await Appointment.create({idempotencyKey:input.idempotencyKey,customerId:customer._id,guest:{name:customer.fullName,phone:customer.phone,email:customer.email},staffId,staffName,startAt:input.startAt,endAt,bookingSource:'web',notes:input.notes,bookingReference:`STW-${Date.now().toString(36).toUpperCase()}`,serviceSnapshot:{serviceId:service?._id,name:serviceData.name,price:serviceData.price,durationMinutes:serviceData.durationMinutes,bufferMinutes:serviceData.bufferMinutes??0},status,statusHistory:[{status}]});
 await safelySyncCalendar(()=>createCalendarEvent(item.toObject()));
 await sendAppointmentEmail(item.toObject(),'created');
 await publishAppointment(appointmentDto(item.toObject())).catch(error=>console.error('Appointment notification failed:',error));
 return res.status(201).json({data:appointmentDto(item.toObject())});
}catch(e){next(e)}});
router.post('/admin/appointments',requireAdmin,async(req,res,next)=>{try{
 const input=booking.extend({customerId:z.string()}).parse(req.body);
 if(!mongoose.isValidObjectId(input.customerId))return res.status(400).json({error:{code:'INVALID_CUSTOMER',message:'Select a registered customer.'}});
 const customer=await Customer.findById(input.customerId).lean();
 if(!customer)return res.status(404).json({error:{code:'CUSTOMER_NOT_FOUND',message:'Customer not found.'}});
 const service=mongoose.isValidObjectId(input.serviceId)?await Service.findById(input.serviceId).lean():await Service.findOne({slug:input.serviceId,active:true}).lean(),serviceData=service;
 if(!serviceData)return res.status(404).json({error:{code:'SERVICE_NOT_FOUND',message:'Service not found'}});
 const endAt=appointmentEnd(input.startAt,serviceData.durationMinutes,serviceData.bufferMinutes??0);assertBookable(input.startAt,endAt);
 const staff=input.staffId&&mongoose.isValidObjectId(input.staffId)?await Staff.findOne({_id:input.staffId,offeredServices:service?._id}).lean():null;
 if(input.staffId&&!staff)return res.status(400).json({error:{code:'STAFF_NOT_QUALIFIED',message:'That team member is not assigned to this service.'}});
 const status=input.status??'confirmed';
 const item=await Appointment.create({idempotencyKey:input.idempotencyKey,customerId:customer._id,guest:{name:customer.fullName,phone:customer.phone,email:customer.email},staffId:staff?._id,staffName:staff?.displayName??input.staffName??'Any available stylist',startAt:input.startAt,endAt,bookingSource:'admin',notes:input.notes,bookingReference:`STW-${Date.now().toString(36).toUpperCase()}`,serviceSnapshot:{serviceId:service?._id,name:serviceData.name,price:serviceData.price,durationMinutes:serviceData.durationMinutes,bufferMinutes:serviceData.bufferMinutes??0},status,statusHistory:[{status}]});
 await safelySyncCalendar(()=>createCalendarEvent(item.toObject()));
 await publishAppointment(appointmentDto(item.toObject())).catch(error=>console.error('Appointment notification failed:',error));
 return res.status(201).json({data:appointmentDto(item.toObject())});
}catch(e){next(e)}});
router.patch('/appointments/:id',requireAdmin,async(req,res,next)=>{try{if(!mongoose.isValidObjectId(req.params.id))return res.status(400).json({error:{code:'INVALID_ID',message:'Invalid appointment id'}});const input=z.object({status:z.enum(['pending','confirmed','checked_in','in_progress','completed','cancelled','rejected','no_show','expired'])}).parse(req.body);const item=await Appointment.findByIdAndUpdate(req.params.id,{$set:{status:input.status},$push:{statusHistory:{status:input.status}}},{new:true}).lean();if(!item)return res.status(404).json({error:{code:'NOT_FOUND',message:'Appointment not found'}});await safelySyncCalendar(()=>['cancelled','rejected','expired'].includes(input.status)?deleteCalendarEvent(item.calendarEventId):updateCalendarEvent(item));await sendAppointmentEmail(item,'status');return res.json({data:appointmentDto(item)})}catch(e){next(e)}});
router.delete('/appointments/:id',requireAdmin,async(req,res,next)=>{try{if(!mongoose.isValidObjectId(req.params.id))return res.status(400).json({error:{code:'INVALID_ID',message:'Invalid appointment id'}});const item=await Appointment.findByIdAndDelete(req.params.id);if(!item)return res.status(404).json({error:{code:'NOT_FOUND',message:'Appointment not found'}});await safelySyncCalendar(()=>deleteCalendarEvent(item.calendarEventId));return res.status(204).send()}catch(e){next(e)}});

export default router;
